{
  "findings": [
    {
      "check_id": "CKV2_AWS_6",
      "title": "S3 bucket lacks a Public Access Block",
      "resource": "aws_s3_bucket.data",
      "severity": "MEDIUM",
      "explanation": "The bucket has no bucket-level Public Access Block, so a future public ACL or bucket policy could expose its data."
    },
    {
      "check_id": "CKV_AWS_21",
      "title": "S3 bucket versioning is disabled",
      "resource": "aws_s3_bucket.data",
      "severity": "HIGH",
      "explanation": "Without versioning, overwritten or deleted objects cannot be recovered, increasing the impact of accidental deletion or malicious modification."
    },
    {
      "check_id": "UNKNOWN",
      "title": "S3 bucket permits destructive deletion",
      "resource": "aws_s3_bucket.data",
      "severity": "MEDIUM",
      "explanation": "The explicit force_destroy setting allows Terraform to delete the bucket along with all stored object versions, undermining data recovery protections."
    }
  ],
  "patched_code": "resource \"aws_s3_bucket\" \"data\" {\n  bucket        = \"${local.resource_prefix.value}-data\"\n  force_destroy = false\n  tags = merge({\n    Name        = \"${local.resource_prefix.value}-data\"\n    Environment = local.resource_prefix.value\n    }, {\n  })\n}\n\nresource \"aws_s3_bucket_public_access_block\" \"data\" {\n  bucket = aws_s3_bucket.data.id\n\n  block_public_acls       = true\n  block_public_policy     = true\n  ignore_public_acls      = true\n  restrict_public_buckets = true\n}\n\nresource \"aws_s3_bucket_versioning\" \"data\" {\n  bucket = aws_s3_bucket.data.id\n\n  versioning_configuration {\n    status = \"Enabled\"\n  }\n}\n",
  "fix_summary": "Added a complete bucket-level Public Access Block, enabled S3 object versioning, and disabled forceful deletion of the bucket and its contents."
}
